"""Reproducible original teaching samples, not a copy of FIPI's closed topic bank.
Shared argumentative building blocks are intentional and disclosed in the UI.
"""
from pathlib import Path
import json,re,hashlib
from urllib.parse import quote
ROOT=Path(__file__).resolve().parents[1]
bank=json.loads((ROOT/'content/essay-bank-v1.json').read_text())
CASES=bank['cases'];UNITS=bank['units']
ANGLES=[
('role','Какую роль играет {n} в жизни человека?',
 'Роль нравственного качества определяется не тем, насколько часто его хвалят. Важно понять, что меняется в отношениях людей благодаря его присутствию или отсутствию. Личная позиция становится опорой, если помогает различать существенное и второстепенное, замечать последствия поступка и сохранять связь с окружающими. При этом никакое качество не существует отдельно от характера: оно раскрывается через выбор, привычки и способность учиться на пережитом.',
 'О значении человеческих ценностей особенно полезно судить по тому, чего лишаются люди, когда перестают им следовать. Внешне жизнь может оставаться благополучной: сохраняются занятия, достижения и привычные разговоры. Но доверие и понимание постепенно исчезают, если за словами нет нравственной работы. Поэтому важен не только отдельный красивый жест, но и повседневный способ обращаться с теми, кто рядом, включая слабых и неудобных собеседников.'),
('trial','Как {n} проявляется в испытаниях?',
 'Испытание делает особенно заметным расстояние между намерением и действием. Пока человек ничем не рискует, ему нетрудно согласиться с благородным правилом. В сложной ситуации приходится выбирать между удобством, страхом, чужой нуждой и верностью себе. Однако трудность не создаёт характер из ничего: в ней обнаруживаются привычные способы думать и поступать. Поэтому повседневные решения подготавливают тот выбор, который позже кажется внезапным и исключительным.',
 'Тяжёлые обстоятельства не следует идеализировать. Они способны и укрепить человека, и сломить его, поэтому чужую слабость нельзя оценивать без знания пережитого. Но наличие давления не делает все решения одинаковыми. Даже ограниченное пространство выбора позволяет поддержать другого, отказаться от лишней жестокости или признать правду. В испытании нравственное начало особенно убедительно там, где сохраняется вопреки страху и отсутствию обещанной награды.'),
('limits','Достаточно ли {g}, чтобы поступать правильно?',
 'Я полагаю, что одного названия ценности недостаточно для правильного решения. Добрый замысел нуждается в понимании обстоятельств, а убеждённость должна допускать проверку. Иначе человек способен причинить вред именно тогда, когда считает себя совершенно правым. Нравственная зрелость предполагает соотнесение нескольких требований: уважения к личности, правдивости, ответственности за последствия. Такая проверка не обесценивает убеждение, а помогает освободить его от самодовольства и односторонности.',
 'На этот вопрос трудно ответить без важного уточнения: нравственные ориентиры действуют не по отдельности. Сильное чувство или верность правилу могут поддерживать решение, но не заменяют внимательности к реальному человеку. Намерение следует проверять вопросами о свободе другого, возможном вреде и собственных мотивах. Поэтому правильный поступок требует не механического следования красивому слову, а самостоятельного рассуждения, готовности услышать возражение и при необходимости изменить способ действия.'),
('identity','Как {n} влияет на становление личности?',
 'Личность складывается не только из способностей и знаний. Не меньшее значение имеют привычки оценивать себя и других, признавать ошибки и выбирать основания поступка. При этом взросление не всегда совпадает с возрастом: человек может долго повторять чужие оценки и лишь позднее начать самостоятельный поиск. Нравственный ориентир способствует развитию тогда, когда становится внутренним убеждением, а не способом получить похвалу родителей, учителя или общества.',
 'Становление личности редко бывает прямым движением от заблуждения к окончательной истине. Встречи, утраты и собственные ошибки меняют представления о важном. Здесь необходимо различать рост и простую приспособляемость: новое мнение ценно не потому, что оно новее, а потому, что помогает глубже понять действительность и ответственность. Воспитывая в себе нравственное качество, человек одновременно учится видеть границы собственного опыта и возможность иной точки зрения.'),
('pressure','Что помогает человеку сохранять {a} вопреки давлению окружения?',
 'Давление окружения бывает не только открытой угрозой. Насмешка, привычка соглашаться со всеми и страх потерять признание могут действовать незаметнее приказа. Противостоять этому помогает понимание причин своего решения и его последствий. Человеку нужна не гордость одиночки, а внутренняя опора, способность искать поддержку и различать разумный совет и требование поступить против совести. Тогда независимость не превращается в отрицание любых общих правил.',
 'Сохранить важное убеждение легче, когда человек понимает, ради кого и ради чего он готов терпеть неудобство. Одного желания выглядеть независимым недостаточно: оно само делает нас зависимыми от зрителей. Опору дают проверенные доводы, опыт значимых отношений и возможность честно назвать собственный страх. При этом нужно сохранять готовность выслушать справедливое возражение. Стойкость отличается от упрямства тем, что защищает смысл, а не непогрешимость своего мнения.'),
('judgment','Можно ли судить о человеке по его отношению к {d}?',
 'Отношение к ценности многое говорит о человеке, но судить следует прежде всего по поступкам и обстоятельствам. Торжественное заявление может скрывать равнодушие, а неловкий собеседник способен оказаться надёжным в беде. Кроме того, один эпизод не исчерпывает личность: важно замечать изменения, мотивы и готовность исправлять причинённое. Поэтому нравственная оценка требует одновременно ясности принципов и осторожности перед соблазном вынести окончательный приговор чужой жизни.',
 'Я считаю, что отношение к нравственному ориентиру действительно раскрывает характер, если речь идёт не об ответе на вопрос, а о жизненной практике. Особенно показательны решения, которые человек принимает без публики и угрозы наказания. Вместе с тем необходимо отличать оценку поступка от унижения личности. Можно признать действие несправедливым и сохранить надежду на изменение человека. Такая позиция требует большей ответственности, чем удобное деление окружающих на навсегда хороших и плохих.'),
('literature','Как литература раскрывает значение {g}?',
 'Литература позволяет увидеть не только внешний результат поступка, но и его внутреннюю историю: надежду, сомнение, самооправдание, позднее раскаяние. Благодаря этому нравственная проблема перестаёт быть отвлечённым правилом. Читатель наблюдает, как одно решение влияет на судьбы нескольких людей, и может проверить собственную первоначальную оценку. При этом художественный пример не заменяет рассуждения: нужно объяснить, какая деталь произведения подтверждает мысль, а не ограничиться названием известной книги.',
 'Писатель раскрывает нравственный вопрос через столкновение характеров, развитие событий и смысловые детали. Один герой произносит верные слова, но не действует; другой помогает молча и остаётся непонятым. Такое сопоставление делает чтение опытом внимания. Мы учимся различать мотив и оправдание, сочувствие и согласие, силу и жестокость. Литературный образ не является готовой инструкцией на все случаи жизни, однако помогает заметить сложность выбора там, где привычное мнение предлагает слишком простой ответ.'),
('experience','Почему жизненный опыт меняет отношение к {d}?',
 'Жизненный опыт меняет взгляд на ценности потому, что переводит отвлечённое знание в личное переживание. Человек узнаёт цену обещания, поддержки или утраты не только из чужого объяснения. Но пережитое не становится мудростью автоматически: одинаковая трудность может научить внимательности или, напротив, закрепить недоверие ко всем. Решающее значение имеет осмысление опыта, способность сопоставить собственную боль с чужой и не объявлять один случай универсальным законом человеческих отношений.',
 'С возрастом и новыми обстоятельствами привычные ответы нередко перестают удовлетворять человека. То, что казалось слабостью, обнаруживает внутреннюю силу; прежний успех может показаться пустым. Однако переоценка не требует полностью отвергать своё прошлое. Полезнее понять, почему прежний взгляд был ограниченным и какие факты его изменили. Так опыт становится основанием более ответственного решения, а не удобным поводом считать доверчивыми и неопытными всех, кто продолжает верить в нравственные ценности.')
]
INTRO=[
 'На вопрос «{title}» нельзя ответить одним определением. Он касается того, как человек выстраивает отношения, понимает собственные обязанности и соотносит желание с действительностью. Для меня убедителен ответ, который подтверждён не громкостью убеждения, а внимательным рассмотрением человеческого опыта. Литературные судьбы позволяют проверить такую позицию и увидеть её сложность.',
 'Размышляя над темой «{title}», я прежде всего обращаю внимание на разницу между провозглашённым идеалом и жизненным решением. Человек может искренне считать себя правым и всё же не замечать чужой боли. Поэтому ответ важно искать не только в словах героя, но и в последствиях его выбора, в том, что он меняет в себе и окружающем мире.'
]
END=[
 'Итак, тема «{n}» касается не отвлечённой характеристики, а способа жить рядом с людьми. Рассмотренные судьбы убеждают: ценность проверяется действием, а её смысл раскрывается с учётом обстоятельств. Я прихожу к выводу, что нравственная зрелость соединяет убеждение с вниманием к другому и готовностью отвечать за выбранный путь. Именно это отличает внутреннюю опору от красивого, но пустого заявления.',
 'Таким образом, разговор на тему «{n}» приводит к вопросу о согласованности человека с собственной совестью. Литература не обещает простого рецепта, зато учит замечать цену решений. Для меня важно не объявить героя безусловно правым, а понять, какое отношение к людям делает его выбор достойным. Такое понимание позволяет осмысленно использовать чужой опыт, сохраняя ответственность за собственные поступки.'
]
def cap(s):return s[0].upper()+s[1:]
def words(s):return len(re.findall(r"[А-Яа-яЁёA-Za-z0-9]+(?:[-’'][А-Яа-яЁёA-Za-z0-9]+)*",s))
def sample(u,angle,title,variant):
 refs=u['refs'];first,second=(refs[0],refs[1]) if variant==0 else (refs[2],refs[0]);a,b=CASES[first],CASES[second]
 opening=INTRO[variant].format(title=title)
 if variant==0:
  paragraphs=[opening,u['thesis'],angle[2],f"{a['author']} в произведении «{a['work']}» раскрывает проблему через человеческую судьбу. "+a['text'],
   'Этот пример особенно важен, потому что показывает не правило вне жизни, а необходимость принять решение среди противоречивых обстоятельств. '+u['caution'],
   f"Другой аспект проблемы раскрывает произведение «{b['work']}», которое написал {b['author']}. "+b['text'],
   'С литературным опытом можно соотнести и обычную жизненную ситуацию. '+u['life']+' Подобный поступок не требует героической обстановки, но показывает, какие убеждения действительно управляют человеком.',END[0].format(**u)]
 else:
  paragraphs=[opening,angle[3],f"Начнём с произведения «{a['work']}» ({a['author']}). "+a['text'],
   u['thesis']+' Вместе с тем необходима оговорка. '+u['caution'],
   f"Для сопоставления обратимся к произведению «{b['work']}» ({b['author']}). "+b['text'],
   'Сопоставление важно не внешним сходством событий. В разных обстоятельствах обнаруживается общая необходимость отличать намерение от результата и учитывать того, кого затрагивает решение. Даже искреннее убеждение нуждается в такой проверке, иначе собственное удобство легко принять за универсальную нравственную правду.',
   'За пределами художественного сюжета вопрос тоже остаётся практическим. '+u['life']+' В такой ситуации личный выбор можно оценить по последствиям для людей, а не по одному заявлению о добрых намерениях.',END[1].format(**u)]
 text='\n\n'.join(paragraphs);wc=words(text)
 assert 350<=wc<=700,(u['key'],angle[0],variant,wc)
 return {'title':'Готовое сочинение '+str(variant+1),'paragraphs':paragraphs,'wordCount':wc,'literaryWorks':[a['work'],b['work']]}
def enrich(c,u,angle,title):
 c.update({'essays':[sample(u,angle,title,v) for v in range(2)],'essayCore':u['key'],'essayAngle':angle[0],
 'essayNotice':'Два полных учебных образца. Составлены с использованием общего аргументного банка: близкие темы могут содержать общие эпизоды и формулировки. Это не официальный закрытый банк ФИПИ и не образцы задания 27 ЕГЭ по конкретному исходному тексту. Используй для анализа структуры и напиши собственную работу.',
 'essaySection': 'Семья и общество' if u['key'] in ['family','generations','home','ancestors','public','patriotism','civic','acceptance'] else 'Природа, культура и познание' if u['key'] in ['nature','science','book','art','language','creativity','critical','work'] else 'Духовно-нравственные ориентиры'})
 # Sources identify works underlying paraphrases, not publishers of these samples.
 c['sources']=[{'url':'https://fipi.ru/itogovoe-sochinenie','label':'ФИПИ: требования и направления итогового сочинения'}]+[{'url':'https://ru.wikipedia.org/wiki/'+quote(CASES[k]['work'].replace(' ','_')),'label':CASES[k]['author']+' · '+CASES[k]['work']} for k in u['refs']]
 return c
f=ROOT/'web-source/library.json';db=json.loads(f.read_text());db['cards']=[c for c in db['cards'] if not c['id'].startswith('essay10-')]
lookup={u['key']:u for u in UNITS}
old=[c for c in db['cards'] if c.get('kind')=='essay']
for c in old:
 key=c['id'].removeprefix('essay-');enrich(c,lookup[key],ANGLES[0],c['title'])
for u in UNITS:
 for angle in ANGLES:
  title=cap(angle[1].format(**u));c={'id':'essay10-'+u['key']+'-'+angle[0],'kind':'essay','subject':'Русский язык','grades':[10,11],'title':title,
   'summary':cap(u['n'])+' · два полных сочинения по 350+ слов · 10–11 классы.',
   'sections':[{'title':'План рассуждения','paragraphs':[u['thesis'],'Литературные аргументы: '+', '.join('«'+CASES[k]['work']+'»' for k in u['refs'])+'.',u['caution']]}],
   'lines':[],'example':'','tags':['сочинение эссе аргумент 10 11',u['n'],u['key']]}
  db['cards'].append(enrich(c,u,angle,title))
essays=[c for c in db['cards'] if c.get('kind')=='essay'];assert len(essays)==436
assert len({c['title'].casefold() for c in essays})==436
hashes=[hashlib.sha256('\n'.join(e['paragraphs']).encode()).hexdigest() for c in essays for e in c['essays']];assert len(set(hashes))==872
f.write_text(json.dumps(db,ensure_ascii=False,indent=2)+'\n')
print('436 topics / 872 complete samples; words:',min(e['wordCount'] for c in essays for e in c['essays']),'-',max(e['wordCount'] for c in essays for e in c['essays']))
